//go:build webembed

package main

import (
	"embed"
	"io/fs"
)

// webdist is generated by build/release.go from the verified web/dist bundle before a
// `-tags webembed` build. It is never committed (it carries its own .gitignore).
//
//go:embed all:webdist
var webdist embed.FS

// embeddedWeb is the production UI bundle compiled into the binary.
func embeddedWeb() (fs.FS, bool) {
	sub, err := fs.Sub(webdist, "webdist")
	if err != nil {
		return nil, false
	}
	return sub, true
}
